package com.muxigame.city;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.storage.LevelResource;

/** Five-minute bounded on-server telemetry. No agents, external polling or recurring model calls. */
public final class RuralMonitor {
    static Path folder(MinecraftServer s){return s.getWorldPath(LevelResource.ROOT).resolve("city_settlements/rural-monitor");}
    static void start(MinecraftServer s,UUID city){var d=RuralSettlement.get(s);d.state.monitored.add(city);d.state.monitorUntil=s.overworld().getGameTime()+12*72000L;d.state.monitorNext=0;d.setDirty();}
    static Map<String,Object> snapshot(MinecraftServer s){var d=RuralSettlement.get(s);var root=new LinkedHashMap<String,Object>();root.put("accountingVersion",2);root.put("timestamp",java.time.OffsetDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).toString());root.put("gameTick",s.overworld().getGameTime());root.put("dayTime",s.overworld().getDayTime());root.put("speed",d.state.speed);root.put("simulationTicks",d.state.simulationTicks);root.put("simulationDay",d.state.simulationDay);root.put("playersOnline",s.getPlayerCount());root.put("monitorUntilTick",d.state.monitorUntil);var cities=new ArrayList<Object>();
        for(UUID cityId:d.state.monitored){var c=CityData.get(s).cities.get(cityId);if(c==null)continue;var city=new LinkedHashMap<String,Object>();city.put("id",cityId);city.put("name",c.name);city.put("audit",d.audit(cityId));city.put("externalBuyer",d.state.externalBuyer.contains(cityId));city.put("pendingWheat",d.state.people.values().stream().filter(p->d.state.families.get(p.family).city.equals(cityId)).mapToInt(p->p.pendingWheat).sum());city.put("stability",CityLiving.stability(CityEconomy.get(s),c));var families=new ArrayList<Object>();long totalSilver=0;
            for(var f:d.state.families.values())if(f.city.equals(cityId)){var row=new LinkedHashMap<String,Object>();var stock=d.stocks(f.id);row.put("family",f.id);row.put("living",RuralRules.members(f,d.state.people).size());row.put("wheat",RuralRules.count(stock,false));row.put("bread",RuralRules.count(stock,true));row.put("meat",RuralMeat.total(stock));row.put("rawMeat",stock.stream().mapToInt(a->java.util.Arrays.stream(a.raw).sum()).sum());row.put("cookedMeat",stock.stream().mapToInt(a->java.util.Arrays.stream(a.cooked).sum()).sum());row.put("freeSlots",RuralRules.capacity(stock));row.put("nextMealDemand",RuralRules.demand(f,d.state.people));long money=f.members.stream().mapToLong(id->CityEconomy.get(s).state.accounts.getOrDefault(CityEconomy.person(id),0L)).sum();row.put("silver",money);totalSilver+=money;
                var persons=new ArrayList<Object>();for(UUID id:f.members){var p=d.state.people.get(id);var person=new LinkedHashMap<String,Object>();person.put("id",id);person.put("role",p.role);person.put("dead",p.dead);person.put("hunger",p.hunger());person.put("nourishment",p.nourishment);person.put("workingTicks",p.totalWorkingTicks);person.put("status",p.workStatus);person.put("hunts",p.hunts);person.put("emptyHunts",p.emptyHunts);person.put("meatProduced",p.meatProduced);person.put("huntSpot",p.huntingSpot);persons.add(person);}row.put("people",persons);families.add(row);
            }city.put("families",families);city.put("familySilver",totalSilver);long market=CityEconomy.get(s).balance("market:"+cityId),publicFunds=CityEconomy.get(s).balance(CityEconomy.treasury(cityId));var members=new HashSet<UUID>();for(var f:d.state.families.values())if(f.city.equals(cityId))members.addAll(f.members);long other=c.residents.stream().filter(id->!members.contains(id)).mapToLong(id->CityEconomy.get(s).balance(CityEconomy.person(id))).sum();city.put("materialMarketSilver",market);city.put("publicSilver",publicFunds);city.put("otherResidentSilver",other);city.put("totalSilver",totalSilver+market+publicFunds+other);cities.add(city);
        }root.put("cities",cities);root.put("allRuralCounters",Map.of("wheatProduced",d.state.wheatProduced,"breadProduced",d.state.breadProduced,"meatProduced",d.state.meatProduced,"meatCooked",d.state.meatCooked,"foodEaten",d.state.foodEaten,"meatSold",d.state.meatSold,"meatBought",d.state.meatBought,"tradedSilver",d.state.tradedSilver,"failedTrades",d.state.failedTrades));root.put("forestCells",d.state.forest.size());return root;
    }
    static void tick(MinecraftServer s){var d=RuralSettlement.get(s);long now=s.overworld().getGameTime();if(d.state.monitored.isEmpty()||now<d.state.monitorNext)return;boolean finalSample=now>=d.state.monitorUntil;d.state.monitorNext=now+(d.state.speed>1?600:6000);
        try{Path folder=folder(s);Files.createDirectories(folder);Path file=folder.resolve("observations.jsonl");if(Files.exists(file)&&Files.size(file)>4*1024*1024){Files.deleteIfExists(folder.resolve("observations-2.jsonl"));if(Files.exists(folder.resolve("observations-1.jsonl")))Files.move(folder.resolve("observations-1.jsonl"),folder.resolve("observations-2.jsonl"));Files.move(file,folder.resolve("observations-1.jsonl"));}String json=CityEconomy.JSON.toJson(snapshot(s));Files.writeString(file,json.replace("\n","").replace("\r","")+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);Files.writeString(folder.resolve("latest.json"),json,StandardCharsets.UTF_8);if(finalSample)d.state.monitored.clear();}
        catch(Exception e){org.slf4j.LoggerFactory.getLogger("RuralMonitor").warn("农村监控写入失败，下个周期重试",e);}d.setDirty();
    }
}
